package com.cryptostrategy.platform.persistence.leaderboard;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.evaluation.api.model.*;import com.cryptostrategy.platform.evaluation.internal.DeterministicEvaluator;import com.cryptostrategy.platform.leaderboard.internal.LeaderboardService;import com.cryptostrategy.platform.persistence.api.*;import com.cryptostrategy.platform.persistence.support.F006DatabaseFixture;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;
class JdbcLeaderboardStoreIntegrationTest{@Test void atomicallyPersistsEntriesAndReusesUnchangedContent(){var source=F006DatabaseFixture.dataSource();F006DatabaseFixture.transaction(source).executeWithoutResult(status->{status.setRollbackOnly();var jdbc=new JdbcTemplate(source);F006DatabaseFixture.seed(jdbc);var result=F006DatabaseFixture.result();new BacktestingPersistenceFactory(source).createResultStore().save(result);var evaluation=new DeterministicEvaluator().evaluate(result,new MetricVersion("metrics-v1"),new RankingVersion("ranking-v1"));new EvaluationPersistenceFactory(source).createStore().save(evaluation);var service=new LeaderboardService(new LeaderboardPersistenceFactory(source).createStore());var first=service.project(result.experimentId(),evaluation.rankingVersion(),10,List.of(evaluation));var same=service.project(result.experimentId(),evaluation.rankingVersion(),10,List.of(evaluation));assertEquals(first.revisionId(),same.revisionId());assertEquals(1,jdbc.queryForObject("select count(*) from experiment.leaderboard_revision where experiment_id=?",Integer.class,result.experimentId().value()));assertEquals(1,jdbc.queryForObject("select count(*) from experiment.leaderboard_entry where leaderboard_revision_id=?",Integer.class,first.revisionId().value()));});}}
